sys_ux_client_script.script:
function handler({
    api,
    event,
    helpers,
    imports
}) {
    function dateTimeStringToTimestamp(dateTimeString) {
        const date = new Date(dateTimeString);
        return date.getTime();
    }
   //個人用予定情報JSONを組み合わせ
    function createEventJSON(eventItem, start, end, startTime, endTime, bgColor, description,k,group) {
        return '{' +
            '"bgColor":"' + bgColor + '",' +
            '"description":"' + description + '",' +
            '"end":"' + end + '",' +
            '"endMS":' + endTime + ',' +
            '"group":"' + group + '",' +
            '"id":"' + eventItem.sys_id.value + k +'",' +
            '"start":"' + start + '",' +
            '"startMS":' + startTime + ',' +
            '"title":"' + eventItem.u_kenmei.value + '"' +
        '}';
    }
    //予定情報を取得
    var event_list = api.data.look_up_multiple_records_1.results;
    //ログインしているユーザー名前を取得
    var user_name = api.context.session.user.userName;

    var str = "[";

    for (var i = 0; i < event_list.length; i++) {
        if (user_name === event_list[i].u_kanren_shien_taishosha.displayValue) {
            //仮登録項目値はチェックを入れて場合、灰色背景になる
            if(event_list[i].u_karitouroku.displayValue == "true"){
             var bgColor = "nds-gray";
            }else{
            //仮登録項目値はチェックを入れてない場合、青色背景になる
              var bgColor = "nds-blue";  
            }
            //予定種別は「組織」の場合、オレンジ背景になる
            if(event_list[i].u_yotei_shubetsu.value == 1){
              var bgColor = "nds-orange";
            }
            //json組み合わせ初期値を設定
            var description = "参加者:" + event_list[i].u_kanren_shien_taishosha.displayValue;
            var repeatFlag = event_list[i].u_kurikaeshi.value;

            var startDate = event_list[i].u_kaishibi.value;
            var startTimeStr = event_list[i].u_kaishi_jikan.value;
            var endDate = event_list[i].u_shuryobi.value;
            var endTimeStr = event_list[i].u_shuryo_jikan.value;

            var start = startDate + " " + startTimeStr;
            var end = endDate + " " + endTimeStr;

            var startMS = dateTimeStringToTimestamp(start);
            var endMS = dateTimeStringToTimestamp(end);
            var weekcount = event_list[i].u_shuuji.displayValue;
            var k = 0;
            //繰り返し処理JSON情報を組み合わせ
            if (repeatFlag && weekcount != 0) {

                const repeatCount = weekcount; // 繰り返し数
                const oneWeekMS = 7 * 24 * 60 * 60 * 1000;

                for (let j = 0; j < repeatCount; j++) {
                    k++;
                    let repStartMS = startMS + j * oneWeekMS;
                    let repEndMS = endMS + j * oneWeekMS;

                    let repStart = new Date(repStartMS).toISOString().slice(0, 16).replace("T", " ");
                    let repEnd = new Date(repEndMS).toISOString().slice(0, 16).replace("T", " ");
                    if(event_list[i].u_yotei_shubetsu.value == 1){
                        var group = "groupIT";
                    }else{
                        var group = event_list[i].u_gurupu.value;
                    }
                    str += createEventJSON(event_list[i], repStart, repEnd, repStartMS, repEndMS, bgColor, description,k,group);
                    str += ",";
                }
            } else {
                //組織表示予定情報groupを設定
                if(event_list[i].u_yotei_shubetsu.value == 1){
                        var group = "groupIT";
                    }else{
                        var group = event_list[i].u_gurupu.value;
                    }
                str += createEventJSON(event_list[i], start, end, startMS, endMS, bgColor, description,k,group);
                str += ",";
            }
        }
    }
   //組み合わせJSON情報を整理
    if (str.trim().endsWith(',')) {
        str = str.trim().slice(0, -1);
    }
    str += "]";

    console.log("event_data:", str);
    api.setState("event_data", str);
}
